const input = $input.first().json;
const body = input.body ?? input;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Body phải là JSON object.');
const expectedInternal=String((typeof $env!=='undefined'?$env.INTERNAL_WEBHOOK_TOKEN:'')||'').trim();
const receivedInternal=String(input.headers?.['x-smart-classroom-internal']||'').trim();
if(expectedInternal && receivedInternal!==expectedInternal) throw new Error('INTERNAL_WEBHOOK_UNAUTHORIZED');
const command_id = body.command_id;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof command_id !== 'string' || !uuid.test(command_id)) throw new Error('command_id phải là UUID hợp lệ.');
return [{json:{command_id,backend_base_url:String((typeof $env!=='undefined'?$env.BACKEND_BASE_URL:'')||'https://smart-classroom-backend-allm.onrender.com').replace(/\/+$/,'')}}];

const command = $input.first().json;
const expected = $('Parse & Validate Input').first().json.command_id;
const id = command.command_id ?? command.id;
if (id !== expected) throw new Error('Backend trả sai command_id.');
const expiresAt = Date.parse(command.expires_at);
if (!Number.isFinite(expiresAt)) throw new Error('Command thiếu expires_at hợp lệ.');
const remaining = expiresAt - Date.now();
return [{json: {
  ...command,
  command_id: id,
  ttl_remaining_ms: remaining,
  skip_dispatch: remaining <= 0
}}];

const result = $input.first().json;
const cmd = result.command;
const expected = $('Parse & Validate Input').first().json.command_id;
if (!cmd || (cmd.command_id ?? cmd.id) !== expected) {
  throw new Error('Backend trả sai command trong kết quả dispatch.');
}
return [{json: {
  workflow_version: 'V3',
  success: true,
  dispatched: true,
  command_id: expected,
  device_id: cmd.device_id,
  command_type: cmd.command_type,
  action: cmd.action,
  level: cmd.level ?? null,
  status: cmd.status,
  dispatch_reason: result.reason ?? null,
  ack_confirmed: false,
  message: 'Đã đưa lệnh vào QUEUED. Chờ simulator claim và gửi ACK.'
}}];

const result = $input.first().json;
const cmd = result.command;
const expected = $('Parse & Validate Input').first().json.command_id;
if (typeof result.dispatched !== 'boolean' || !cmd || (cmd.command_id ?? cmd.id) !== expected || typeof cmd.status !== 'string') {
  throw new Error('Backend response không đúng contract dispatch.');
}
if (result.dispatched) throw new Error('Backend báo dispatched nhưng trạng thái không phải QUEUED.');
return [{json: {
  workflow_version: 'V3',
  success: false,
  dispatched: false,
  command_id: expected,
  device_id: cmd.device_id,
  command_type: cmd.command_type,
  action: cmd.action,
  level: cmd.level ?? null,
  status: cmd.status,
  dispatch_reason: result.reason ?? 'DISPATCH_BLOCKED',
  ack_confirmed: cmd.status === 'ACK',
  can_retry: false,
  message: 'Backend không phát lệnh ở lượt này. Xem dispatch_reason; không tự retry lệnh đã bị chặn.'
}}];

const cmd = $input.first().json;
const expected = $('Parse & Validate Input').first().json.command_id;
if ((cmd.command_id ?? cmd.id) !== expected || typeof cmd.status !== 'string') {
  throw new Error('Backend response không đúng contract command status.');
}
return [{json: {
  workflow_version: 'V3',
  success: false,
  dispatched: false,
  command_id: expected,
  device_id: cmd.device_id,
  command_type: cmd.command_type,
  action: cmd.action,
  level: cmd.level ?? null,
  status: cmd.status,
  dispatch_reason: 'NOT_PENDING',
  ack_confirmed: cmd.status === 'ACK',
  can_retry: false,
  message: 'Lệnh không còn PENDING. Không phát lại; xem status để biết trạng thái hiện tại.'
}}];
